from docx import Document
import re

# Load the filled document
doc = Document('/root/offer_letter_filled.docx')

# Display the content
print("=== Offer Letter Content ===")
for paragraph in doc.paragraphs:
    if paragraph.text.strip():
        print(paragraph.text)

# Check for any remaining placeholders
all_text = '\n'.join([p.text for p in doc.paragraphs])

# Also check tables
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for paragraph in cell.paragraphs:
                all_text += '\n' + paragraph.text

if '{{' in all_text:
    print("\n=== WARNING: Unfilled placeholders found ===")
    placeholders = re.findall(r'\{\{[^}]+\}\}', all_text)
    print(f"Remaining placeholders: {set(placeholders)}")
else:
    print("\n=== SUCCESS: All placeholders filled ===")

# Check for conditional markers
if 'IF_RELOCATION' in all_text or 'END_IF_RELOCATION' in all_text:
    print("WARNING: Conditional markers still present")
else:
    print("SUCCESS: Conditional markers removed")
EOF
